import { useEffect, useState } from 'react';
import { ReadingProgress } from './ReadingProgress';
import { ArticleHeader } from './ArticleHeader';
import { ArticleBody } from './ArticleBody';
import { CommentSection } from './CommentSection';

export function BlogPost() {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const onScroll = () => {
      const el = document.documentElement;
      const scrolled = el.scrollTop;
      const total = el.scrollHeight - el.clientHeight;
      setProgress(total > 0 ? (scrolled / total) * 100 : 0);
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <div className="min-h-screen bg-white font-sans">
      <ReadingProgress value={progress} />

      {/* Nav */}
      <nav className="sticky top-0 z-40 border-b border-slate-100 bg-white/90 backdrop-blur-sm px-6 py-4 flex items-center justify-between">
        <span className="font-bold text-slate-800">The Dispatch</span>
        <div className="flex items-center gap-4 text-sm">
          <a href="#" className="text-slate-500 hover:text-slate-800">Articles</a>
          <a href="#" className="text-slate-500 hover:text-slate-800">Newsletter</a>
          <button className="bg-violet-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold hover:bg-violet-500 transition-colors">Subscribe</button>
        </div>
      </nav>

      <div className="max-w-3xl mx-auto px-4 py-12">
        <ArticleHeader />
        <ArticleBody />
        <CommentSection />
      </div>
    </div>
  );
}

