import { useState, FormEvent } from 'react';
import { ThumbsUp } from 'lucide-react';

const INITIAL_COMMENTS = [
  { id: 1, author: 'Bob Chen', initials: 'BC', time: '2h ago', body: 'Fantastic article. The registry-as-schema idea is something we have been discussing internally for months.', likes: 14 },
  { id: 2, author: 'Sara Kim',  initials: 'SK', time: '4h ago', body: 'Really appreciate the practical advice at the end. Starting small and iterating is exactly the right approach.', likes: 8 },
  { id: 3, author: 'Dev Patel', initials: 'DP', time: '1d ago', body: 'Any plans to open-source the registry tooling? Would love to see how this integrates with Storybook.', likes: 5 },
];

export function CommentSection() {
  const [comments, setComments] = useState(INITIAL_COMMENTS);
  const [body, setBody] = useState('');
  const [liked, setLiked] = useState<Set<number>>(new Set());

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!body.trim()) return;
    setComments(prev => [{ id: Date.now(), author: 'You', initials: 'YO', time: 'Just now', body: body.trim(), likes: 0 }, ...prev]);
    setBody('');
  };

  const toggleLike = (id: number) => {
    setLiked(prev => {
      const next = new Set(prev);
      if (next.has(id)) { next.delete(id); } else { next.add(id); }
      return next;
    });
    setComments(prev => prev.map(c => c.id === id ? { ...c, likes: c.likes + (liked.has(id) ? -1 : 1) } : c));
  };

  return (
    <section>
      <h2 className="text-xl font-bold text-slate-800 mb-5">{comments.length} Comments</h2>

      {/* New comment */}
      <form onSubmit={handleSubmit} className="mb-8">
        <textarea
          value={body}
          onChange={e => setBody(e.target.value)}
          placeholder="Share your thoughts…"
          rows={3}
          className="w-full px-4 py-3 rounded-xl border border-slate-200 text-sm text-slate-700 placeholder:text-slate-400 focus:border-violet-400 focus:outline-none focus:ring-2 focus:ring-violet-100 resize-none transition-all"
        />
        <div className="flex justify-end mt-2">
          <button type="submit" disabled={!body.trim()} className="px-4 py-2 bg-violet-600 hover:bg-violet-500 disabled:opacity-40 text-white text-sm font-semibold rounded-lg transition-colors">
            Post comment
          </button>
        </div>
      </form>

      {/* List */}
      <div className="space-y-5">
        {comments.map(c => (
          <div key={c.id} className="flex gap-3">
            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-violet-400 to-fuchsia-400 flex items-center justify-center text-white text-xs font-semibold flex-shrink-0">{c.initials}</div>
            <div className="flex-1">
              <div className="flex items-baseline justify-between">
                <span className="text-sm font-semibold text-slate-800">{c.author}</span>
                <span className="text-xs text-slate-400">{c.time}</span>
              </div>
              <p className="text-sm text-slate-600 mt-1 leading-relaxed">{c.body}</p>
              <button
                onClick={() => toggleLike(c.id)}
                className={`mt-2 flex items-center gap-1.5 text-xs transition-colors ${
                  liked.has(c.id) ? 'text-violet-600' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                <ThumbsUp className="h-3 w-3" /> {c.likes}
              </button>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
